    internal InnerCampaignEmailOutboundConfigFactory DefaultOutboundConfigFactory { get; set; }

    protected override Humidifier.ConnectCampaignsV2.CampaignTypes.EmailChannelSubtypeConfig Create()
    {
        var emailChannelSubtypeConfigResult = CreateEmailChannelSubtypeConfig();
        factoryAction?.Invoke(emailChannelSubtypeConfigResult);

        return emailChannelSubtypeConfigResult;
    }

    private Humidifier.ConnectCampaignsV2.CampaignTypes.EmailChannelSubtypeConfig CreateEmailChannelSubtypeConfig()
    {
        var emailChannelSubtypeConfigResult = new Humidifier.ConnectCampaignsV2.CampaignTypes.EmailChannelSubtypeConfig();

        return emailChannelSubtypeConfigResult;
    }
    public override void CreateChildren(Humidifier.ConnectCampaignsV2.CampaignTypes.EmailChannelSubtypeConfig result)
    {
        base.CreateChildren(result);

        result.OutboundMode ??= OutboundModeFactory?.Build();
        result.DefaultOutboundConfig ??= DefaultOutboundConfigFactory?.Build();
    }

} // End Of Class

